package com.manageinvoice.vendors;
import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
import com.manageinvoice.common.security.AuthenticatedUser;
@RestController @RequestMapping("/api/v1/vendors") public class VendorController { private final VendorService service; public VendorController(VendorService service){this.service=service;} @GetMapping public List<Vendor> list(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId){return service.list(workspaceId,user.id());} @PostMapping public Vendor create(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId,@RequestBody VendorService.CreateRequest request){return service.create(workspaceId,user.id(),request);} @PutMapping("/{vendorId}") public Vendor update(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId,@PathVariable UUID vendorId,@RequestBody VendorService.CreateRequest request){return service.update(workspaceId,user.id(),vendorId,request);} @DeleteMapping("/{vendorId}") public org.springframework.http.ResponseEntity<Void> delete(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId,@PathVariable UUID vendorId){service.delete(workspaceId,user.id(),vendorId);return org.springframework.http.ResponseEntity.noContent().build();} }
